// ZeroNote URI 读取插件 —— 构建脚本。
//
// 与 `tauri-plugin-statusbar` 同构，`tauri_plugin::Builder` 做两件事：
//   ① 在 `permissions/autogenerated/` 下按 COMMANDS 生成权限文件
//      （`read_content_uri` → `allow-read-content-uri`）
//   ② `.android_path("android")` 告诉 Tauri CLI 本插件的 Android 模块在哪 ——
//      CLI 据此自动写 `gen/android/tauri.settings.gradle` 的 include 行，
//      **不需要手改 gradle**。
const COMMANDS: &[&str] = &["read_content_uri"];

fn main() {
  tauri_plugin::Builder::new(COMMANDS)
    .android_path("android")
    .build();
}
